contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0);
        // Deploy adversarial Owner contract that reverts on receive
        RevertingOwner owner = new RevertingOwner();
        // Transfer ownership to the adversarial contract
        vm.prank(address(c).balance == 0 ? address(0) : address(c)); // not needed; we'll use prank on c's deployer which is this test contract
        // Actually: Owner is set in constructor to msg.sender of deploy. We deploy c in setUp, so Owner is this test contract.
        // We need to change Owner to the adversarial contract. We can use Command to transfer ownership? No, Owner is immutable after deploy.
        // Re-deploy c with the adversarial contract as Owner:
        // We'll deploy a new C where the adversarial contract is the deployer, making it Owner.
        // But setUp already deploys c. We can just re-deploy in the test.
        // Reset: we can deploy a fresh C via the adversarial contract.
        vm.prank(address(owner));
        c = new C();
        // Fund c with amount
        vm.deal(address(c), amount);
        uint256 preBalance = address(c).balance;
        require(preBalance == amount, "funding failed");
        // Caller (EOA) calls withdraw; msg.sender == caller, Owner == adversarial contract
        vm.prank(caller);
        bool success;
        try c.withdraw() { success = true; } catch { success = false; }
        // Rule: If withdraw succeeds, contract balance must be zero.
        assertTrue(!success || address(c).balance == 0);
    }
}

