pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address adr, uint256 amount, bytes calldata data) public {
        vm.assume(adr != address(c)); // the bug only manifests when adr != c, otherwise both call c
        vm.assume(address(this).balance == 0); // clean test contract balance

        // deploy a reverter helper that will cause the external call to fail
        Reverter reverter = new Reverter();
        address target = reverter; // use the reverter as the target address

        // fund c's Owner (which is this test contract initially) and send the Command call as Owner
        vm.deal(address(this), amount);
        uint256 ownerBalBefore = address(this).balance;

        vm.prank(address(this)); // Owner = test contract
        try c.Command{value: amount}(target, data) {
            // succeeded
        } catch {
            // failed
        }

        uint256 ownerBalAfter = address(this).balance;

        // The reference C forwards the call to target, which is Reverter, so the call always reverts.
        // Because the low-level call reverts, the entire Command call reverts, and the owner's balance
        // should be unchanged (amount returned). For the buggy version, Command calls address(this),
        // the self-call succeeds, so Ether stays in C and the owner's balance decreases by amount.
        assertEq(ownerBalAfter, ownerBalBefore);
    }
}

contract Reverter {
    fallback() external payable {
        revert("Reverter always fails");
    }
}

